// isPolicyReferencedByIngressAnnotation reports whether the Ingress lists the given policy
// in its policies annotation (configs.PoliciesAnnotation). The annotation value is a
// comma-separated list of entries, each of which may be a bare name (matched when the
// Ingress namespace equals the policy namespace) or a "namespace/name" reference.
func isPolicyReferencedByIngressAnnotation(policyNamespace string, policyName string, ing *networking.Ingress) bool {
	value, exists := ing.Annotations[configs.PoliciesAnnotation]
	if !exists {
		return false
	}

	for _, policy := range strings.Split(value, ",") {
		policy = strings.TrimSpace(policy)
		if policy == policyNamespace+"/"+policyName {
			return true
		}
		if policyNamespace == ing.Namespace && policy == policyName {
			return true
		}
	}

	return false
